```python
def search_range(nums, target):
    """LC 34: 返回 [起始位置, 结束位置]，不存在返回 [-1, -1]"""
    def find_first(nums, target):
        left, right, result = 0, len(nums) - 1, -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                result = mid; right = mid - 1   # 记录并继续往左找
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

def find_last(nums, target):
        left, right, result = 0, len(nums) - 1, -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                result = mid; left = mid + 1    # 记录并继续往右找
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    return [find_first(nums, target), find_last(nums, target)]

将数组分成 k 个子数组，使子数组和的最大值最小。

```python
def split_array(nums, k):
    def can_split(max_sum):
        """判断：子数组和不超过 max_sum 的前提下，能否分成 <= k 段"""
        count = 1          # 当前段数
        current_sum = 0
        for num in nums:
            if current_sum + num > max_sum:
                count += 1
                current_sum = num
                if count > k:
                    return False
            else:
                current_sum += num
        return True

    lo, hi = max(nums), sum(nums)  # 答案范围：单个最大元素 ~ 整个数组之和
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if can_split(mid):
            hi = mid       # mid 可行，尝试更小的答案
        else:
            lo = mid + 1   # mid 不可行，答案需要更大
    return lo
```

