思路和 LC 76 类似，只不过窗口大小固定为 `len(p)`。

```python
from collections import Counter

def findAnagrams(s: str, p: str) -> list:
    if len(s) < len(p):
        return []

    need = Counter(p)
    window = {}
    valid = 0
    required = len(need)
    result = []
    left = 0

    for right in range(len(s)):
        # 扩展窗口
        c = s[right]
        if c in need:
            window[c] = window.get(c, 0) + 1
            if window[c] == need[c]:
                valid += 1

        # 当窗口长度达到 p 的长度时，判断并收缩
        if right - left + 1 == len(p):
            if valid == required:
                result.append(left)

            # 左边界移出
            d = s[left]
            if d in need:
                if window[d] == need[d]:
                    valid -= 1
                window[d] -= 1
            left += 1

    return result
```

