def dfs_iterative(start, graph):
    """用栈模拟 DFS，避免递归深度过大"""
    stack = [start]
    visited = {start}
    while stack:
        node = stack.pop()        # 栈顶弹出
        process(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)
