def bfs(start, graph):
    """通用 BFS 模板"""
    queue = deque([start])
    visited = {start}
    while queue:
        node = queue.popleft()    # 队头弹出（先进先出）
        process(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
