def solve(n, k, a):
    S = [0] * (n + 1)
    P = [0] * (n + 1)
    for i in range(1, n + 1):
        S[i] = S[i - 1] + a[i]
    for i in range(1, n + 1):
        P[i] = P[i - 1] + S[i]

    def count_le(X):
        cnt = 0
        for l in range(1, n + 1):
            C = P[l - 1] - (l - 1) * S[l - 1]
            target = X + C
            lo2, hi2, best = l, n, l - 1
            while lo2 <= hi2:
                mid = (lo2 + hi2) // 2
                if P[mid] - mid * S[l - 1] <= target:
                    best = mid
                    lo2 = mid + 1
