    n = int(data[0]); k = int(data[1])
    arr = [int(x) for x in data[2:2 + n]]
    # 特判 k = 1：单元素自然合法，答案为数组最小值
    if k == 1:
        sys.stdout.write(str(min(arr)))
        return
    # 缓存同值分解结果，避免重复跑 Pollard-Rho
