    "amount": {"金额", "费用", "应付金额", "合计金额"},
}


def normalize_header(value: object) -> str:
    if value is None:
        return ""
    return "".join(str(value).strip().lower().split())


def find_header_row(raw, scan_rows: int = 20) -> int | None:
    aliases = {
        normalize_header(alias)
        for names in HEADER_ALIASES.values()
        for alias in names
    }
    best_row = None
    best_score = 0

for row_index in range(min(scan_rows, len(raw))):
        values = {normalize_header(v) for v in raw.iloc[row_index].tolist()}
        score = len(values & aliases)
        if score > best_score:
            best_row = row_index
            best_score = score

    return best_row if best_score >= 2 else None
