def build_column_mapping(columns) -> dict[str, str]:
    mapping = {}
    for column in columns:
        normalized = normalize_header(column)
        for target, aliases in HEADER_ALIASES.items():
            normalized_aliases = {normalize_header(x) for x in aliases}
