```python
class QueuePolicy:
    def choose_next(self, waiting_visits):
        raise NotImplementedError


class PriorityPolicy(QueuePolicy):
    def choose_next(self, waiting_visits):
        return min(
            waiting_visits,
            key=lambda item: (-item.priority, item.created_at),
        )
