import sys
from math import exp


def merge(left, right):
    if left is None:
        return right
    if right is None:
        return left

    lm, ld, lv = left
    rm, rd, rv = right
    maximum = max(lm, rm)
    left_scale = exp(lm - maximum)
    right_scale = exp(rm - maximum)

    return (
        maximum,
        ld * left_scale + rd * right_scale,
        lv * left_scale + rv * right_scale,
    )


