def feasible(a, n, m, G):
    if G == 0:
        return True
    bad = []
    for i in range(n - 1):
        if a[i + 1] - a[i] < G:
            bad.append(i)
            if len(bad) > 2:
                return False
    if not bad:
        return True

    if len(bad) == 1:
        cands = (bad[0], bad[0] + 1)
    elif len(bad) == 2 and bad[1] == bad[0] + 1:
        cands = (bad[0] + 1,)
    else:
        return False

    for k in cands:
        if 0 < k < n - 1 and a[k + 1] - a[k - 1] < G:
            continue
        if any(i != k - 1 and i != k for i in bad):
            continue

        first = a[1] if k == 0 else a[0]
        last = a[n - 2] if k == n - 1 else a[n - 1]

if first - G >= 1:
            return True
        if last + G <= m:
            return True
        if 0 < k < n - 1 and a[k + 1] - a[k - 1] >= 2 * G:
            return True
        for i in range(n - 1):
            if i == k - 1 or i == k:
                continue
            if a[i + 1] - a[i] >= 2 * G:
                return True
    return False

